export const SESSION_COOKIE = 'session_token';

export function setSession(res: Response, token: string) {
  res.cookie(SESSION_COOKIE, token, { httpOnly: true, sameSite: 'lax' });
}

export function readSession(req: Request) {
  return req.cookies[SESSION_COOKIE];
}

import CookieManager from '@react-native-cookies/cookies';

export async function sessionToken(baseUrl: string) {
  const cookies = await CookieManager.get(baseUrl);
  return cookies['session_token']?.value;
}

